    21  spng_ctx *spng_ctx_new2(struct spng_alloc *alloc, int flags)
    22  {
    23      if(alloc == NULL) return NULL;
    24      if(flags) return NULL;
    25
    26      if(alloc->malloc_fn == NULL) return NULL;
    27      if(alloc->realloc_fn == NULL) return NULL;
    28      if(alloc->calloc_fn == NULL) return NULL;
    29      if(alloc->free_fn == NULL) return NULL;
    30
    31      spng_ctx *ctx = alloc->calloc_fn(1, sizeof(spng_ctx));
    32      if(ctx == NULL) return NULL;
    33
    34      memcpy(&ctx->alloc, alloc, sizeof(struct spng_alloc));
    35
    36      ctx->max_chunk_size = png_u32max;
    37      ctx->chunk_cache_limit = SIZE_MAX;
    38
    39      ctx->valid_state = 1;
    40
    41      return ctx;
    42  }
