    44  void spng_ctx_free(spng_ctx *ctx)
    45  {
    46      if(ctx == NULL) return;
    47
    48      if(ctx->streaming && ctx->data != NULL) spng__free(ctx, ctx->data);
    49
    50      if(ctx->exif.data != NULL && !ctx->user_exif) spng__free(ctx, ctx->exif.data);
    51
    52      if(ctx->iccp.profile != NULL && !ctx->user_iccp) spng__free(ctx, ctx->iccp.profile);
    53
    54      if(ctx->gamma_lut != NULL) spng__free(ctx, ctx->gamma_lut);
    55
    56      if(ctx->splt_list != NULL && !ctx->user_splt)
    57      {
    58          uint32_t i;
    59          for(i=0; i < ctx->n_splt; i++)
    60          {
    61              if(ctx->splt_list[i].entries != NULL) spng__free(ctx, ctx->splt_list[i].entries);
    62          }
    63          spng__free(ctx, ctx->splt_list);
    64      }
    65
    66      if(ctx->text_list != NULL && !ctx->user_text)
    67      {
    68          uint32_t i;
    69          for(i=0; i< ctx->n_text; i++)
    70          {
    71              if(ctx->text_list[i].text != NULL) spng__free(ctx, ctx->text_list[i].text);
    72              if(ctx->text_list[i].language_tag != NULL) spng__free(ctx, ctx->text_list[i].language_tag);
    73              if(ctx->text_list[i].translated_keyword != NULL) spng__free(ctx, ctx->text_list[i].translated_keyword);
    74          }
    75          spng__free(ctx, ctx->text_list);
    76      }
    77
    78      spng_free_fn *free_func = ctx->alloc.free_fn;
    79
    80      memset(ctx, 0, sizeof(spng_ctx));
    81
    82      free_func(ctx);
    83  }
